#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
#include <algorithm>
#include <string>
#include <vector>
namespace py = pybind11;
struct T{int x,y,harvest,until,yield,cap,birth;bool has_harvest;std::string crop;std::vector<int> water;};
struct P{int x,y,birth;std::string crop;};
struct B{double score=0;long long gross=0;int now=0,x=0,y=0,wheat=0,carrot=0;std::vector<P> path;std::vector<int> used;};
static bool path_less(const std::vector<P>&a,const std::vector<P>&b){size_t n=std::min(a.size(),b.size());for(size_t i=0;i<n;++i){if(a[i].x!=b[i].x)return a[i].x<b[i].x;if(a[i].y!=b[i].y)return a[i].y<b[i].y;if(a[i].crop!=b[i].crop)return a[i].crop<b[i].crop;if(a[i].birth!=b[i].birth)return a[i].birth<b[i].birth;}return a.size()<b.size();}
static bool key_less(const B&a,const B&b){if(a.score!=b.score)return a.score>b.score;if(a.gross!=b.gross)return a.gross>b.gross;if(a.now!=b.now)return a.now<b.now;if(path_less(a.path,b.path))return true;if(path_less(b.path,a.path))return false;return false;}
static int gain(const T&t,int arrival,int day){if(!t.has_harvest||t.harvest<=arrival)return 0;int extra=0,base=t.yield;for(int w:t.water){int d=w/24;if(arrival<w&&w<=t.harvest&&day<=d&&d<=day+2&&d>t.until)++extra;base+=(d<=t.until)?2:1;}return std::max(0,std::min(extra,t.cap-base));}
static T parse(py::handle xyh,py::handle th){auto xy=py::reinterpret_borrow<py::sequence>(xyh);auto d=py::reinterpret_borrow<py::dict>(th);T t{};t.x=py::cast<int>(xy[0]);t.y=py::cast<int>(xy[1]);py::object h=d[py::str("harvest")];t.has_harvest=!h.is_none();t.harvest=t.has_harvest?py::cast<int>(h):0;t.until=py::cast<int>(d[py::str("until")]);t.yield=py::cast<int>(d[py::str("yield")]);t.cap=py::cast<int>(d[py::str("cap")]);t.birth=py::cast<int>(d[py::str("birth")]);t.crop=py::cast<std::string>(d[py::str("crop")]);for(py::handle w:py::reinterpret_borrow<py::sequence>(d[py::str("water")]))t.water.push_back(py::cast<int>(w));return t;}
static py::tuple r51(py::dict targets,int ready,py::sequence start,int day,int wp,int cp,int fert){std::vector<T> ts;ts.reserve(py::len(targets));for(auto it:targets)ts.push_back(parse(it.first,it.second));B init;init.now=ready;init.x=py::cast<int>(start[0]);init.y=py::cast<int>(start[1]);std::vector<B> beam{init};bool have=false;B best;int lim=day*24+23;for(int depth=0;depth<8;++depth){std::vector<B> ex;ex.reserve(beam.size()*ts.size());for(const B&s:beam)for(size_t i=0;i<ts.size();++i){if(std::find(s.used.begin(),s.used.end(),(int)i)!=s.used.end())continue;const T&t=ts[i];int arr=s.now+std::abs(s.x-t.x)+std::abs(s.y-t.y);if(arr>=lim)continue;int g=gain(t,arr,day);if(!g)continue;int price=t.crop=="WHEAT"?wp:(t.crop=="CARROT"?cp:-1);if(price<0)throw std::runtime_error("unsupported crop");B n=s;n.gross=s.gross+(long long)g*price;n.now=arr+1;n.x=t.x;n.y=t.y;n.path.push_back(P{t.x,t.y,t.birth,t.crop});n.used.push_back((int)i);n.wheat+=t.crop=="WHEAT"?g:0;n.carrot+=t.crop=="CARROT"?g:0;n.score=(double)n.gross-1.5*(double)fert*n.path.size();ex.push_back(std::move(n));}if(ex.empty())break;std::stable_sort(ex.begin(),ex.end(),key_less);if(ex.size()>8)ex.resize(8);beam=std::move(ex);if(depth>=2){if(!have||key_less(beam[0],best)){best=beam[0];have=true;}}}py::list path;py::dict u;u[py::str("WHEAT")]=have?best.wheat:0;u[py::str("CARROT")]=have?best.carrot:0;if(have)for(auto&p:best.path)path.append(py::make_tuple(p.x,p.y,p.crop,p.birth));return py::make_tuple(path,u);}
static bool eq(py::handle a,py::handle b){int r=PyObject_RichCompareBool(a.ptr(),b.ptr(),Py_EQ);if(r<0)throw py::error_already_set();return r!=0;}
static double r37_similarity(py::dict obs){auto farms=py::reinterpret_borrow<py::sequence>(obs[py::str("farms")]);int player=py::cast<int>(obs[py::str("player")]);auto own=py::reinterpret_borrow<py::dict>(farms[player]);auto rival=py::reinterpret_borrow<py::dict>(farms[1-player]);if(!eq(own[py::str("unlocked_quadrants")],rival[py::str("unlocked_quadrants")]))return 0.0;auto arows=py::reinterpret_borrow<py::sequence>(own[py::str("tiles")]);auto brows=py::reinterpret_borrow<py::sequence>(rival[py::str("tiles")]);int matches=0,total=0;size_t nr=std::min((size_t)py::len(arows),(size_t)py::len(brows));for(size_t y=0;y<nr;++y){auto ar=py::reinterpret_borrow<py::sequence>(arows[y]);auto br=py::reinterpret_borrow<py::sequence>(brows[y]);size_t nc=std::min((size_t)py::len(ar),(size_t)py::len(br));for(size_t x=0;x<nc;++x){py::handle ah=ar[x],bh=br[x];py::object ac=py::none(),aa=py::none(),bc=py::none(),ba=py::none();if(py::isinstance<py::dict>(ah)){auto d=py::reinterpret_borrow<py::dict>(ah);if(d.contains(py::str("crop")))ac=py::reinterpret_borrow<py::object>(d[py::str("crop")]);if(d.contains(py::str("animal")))aa=py::reinterpret_borrow<py::object>(d[py::str("animal")]);}if(py::isinstance<py::dict>(bh)){auto d=py::reinterpret_borrow<py::dict>(bh);if(d.contains(py::str("crop")))bc=py::reinterpret_borrow<py::object>(d[py::str("crop")]);if(d.contains(py::str("animal")))ba=py::reinterpret_borrow<py::object>(d[py::str("animal")]);}bool aempty=ac.is_none()&&aa.is_none(),bempty=bc.is_none()&&ba.is_none();if(!aempty||!bempty){++total;if(eq(ac,bc)&&eq(aa,ba))++matches;}}}return total>=8?(double)matches/(double)total:0.0;}
PYBIND11_MODULE(_kaggriculture_native,m){m.def("r51_input_path_core",&r51);m.def("r37_similarity",&r37_similarity);}
